begin;
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions,pg_temp;
select no_plan();
create function pg_temp.attempt(a text,d jsonb,expected text default '00000') returns boolean language plpgsql security invoker as $$
begin perform public.campusfind_workflow(a,d); return expected='00000';
exception when others then return sqlstate=expected; end; $$;
insert into auth.users(id,email) values ('81000000-0000-4000-8000-000000000001','81000000-0000-4000-8000-000000000001@example.invalid'),('81000000-0000-4000-8000-000000000002','81000000-0000-4000-8000-000000000002@example.invalid'),('81000000-0000-4000-8000-000000000003','81000000-0000-4000-8000-000000000003@example.invalid'),('81000000-0000-4000-8000-000000000004','81000000-0000-4000-8000-000000000004@example.invalid');
update profiles set role='ADMIN' where id='81000000-0000-4000-8000-000000000004';
insert into items(id,reporter_id,type,title,category,location,event_date) values ('82000000-0000-4000-8000-000000000001','81000000-0000-4000-8000-000000000001','LOST','SQL lost fixture','Other','Library',current_date);
insert into items(id,reporter_id,type,title,category,location,event_date) values ('82000000-0000-4000-8000-000000000002','81000000-0000-4000-8000-000000000001','LOST','SQL lost fixture','Other','Library',current_date);
insert into items(id,reporter_id,type,title,category,location,event_date) values ('82000000-0000-4000-8000-000000000003','81000000-0000-4000-8000-000000000001','FOUND','SQL lost fixture','Other','Library',current_date);
select ok(not has_function_privilege('authenticated','campusfind_private.run_workflow_base(text,jsonb)','EXECUTE'),'Members cannot bypass LOST verification via base function');
