select ok(pg_temp.attempt('submit_found_response','{"item_id": "82000000-0000-4000-8000-000000000001", "request_id": "83000000-0000-4000-8000-000000000001", "proof_text": "Distinct private description of the held wallet"}','42501'),'Reporter cannot respond to own LOST');
