select ok(pg_temp.attempt('submit_found_response','{"item_id": "82000000-0000-4000-8000-000000000003", "request_id": "83000000-0000-4000-8000-000000000001", "proof_text": "Distinct private description of the held wallet"}','42501'),'Found response remains LOST-only');
select ok(pg_temp.attempt('submit_found_response','{"item_id": "82000000-0000-4000-8000-000000000001", "request_id": "83000000-0000-4000-8000-000000000001", "proof_text": "Distinct private description of the held wallet"}','00000'),'Holder responds to LOST');
select ok(pg_temp.attempt('submit_found_response','{"item_id": "82000000-0000-4000-8000-000000000001", "request_id": "83000000-0000-4000-8000-000000000001", "proof_text": "Distinct private description of the held wallet"}','00000'),'Response replay is idempotent');
select ok(pg_temp.attempt('submit_found_response','{"item_id": "82000000-0000-4000-8000-000000000001", "request_id": "83000000-0000-4000-8000-000000000001", "proof_text": "Distinct private description of the held wallet changed"}','22023'),'Idempotency collision denied');
select ok(pg_temp.attempt('submit_found_response','{"item_id": "82000000-0000-4000-8000-000000000001", "request_id": "83000000-0000-4000-8000-000000000003", "proof_text": "Distinct private description of the held wallet"}','23505'),'Duplicate active response denied');
select ok(pg_temp.attempt('submit_owner_proof','{"claim_id": "83000000-0000-4000-8000-000000000001", "proof_text": "Secret owner detail not in the public LOST listing"}','22023'),'No evidence before selection');
set local role authenticated; set local request.jwt.claim.sub='81000000-0000-4000-8000-000000000003';
select ok(not exists(select 1 from claims where id='83000000-0000-4000-8000-000000000001'),'Other user cannot read finder response');
select ok(pg_temp.attempt('submit_found_response','{"item_id": "82000000-0000-4000-8000-000000000001", "request_id": "83000000-0000-4000-8000-000000000002", "proof_text": "Distinct private description of the held wallet"}','00000'),'Another holder may respond');
set local role authenticated; set local request.jwt.claim.sub='81000000-0000-4000-8000-000000000001';
select ok(pg_temp.attempt('review_claim','{"claim_id": "83000000-0000-4000-8000-000000000001", "decision": "APPROVED"}','00000'),'Owner selects response');
select ok((select status='OPEN' from items where id='82000000-0000-4000-8000-000000000001'),'items OPEN');
select ok((select status='REJECTED' from claims where id='83000000-0000-4000-8000-000000000002'),'claims REJECTED');
select ok(pg_temp.attempt('resolve_lost','{"item_id": "82000000-0000-4000-8000-000000000001"}','22023'),'Selected response cannot bypass two-party return');
