select ok(pg_temp.attempt('verify_owner','{"claim_id": "83000000-0000-4000-8000-000000000001", "decision": "APPROVED"}','22023'),'Holder cannot verify missing proof');
select ok(pg_temp.attempt('submit_owner_proof','{"claim_id": "83000000-0000-4000-8000-000000000001", "proof_text": "Secret owner detail not in the public LOST listing"}','42501'),'Holder cannot impersonate owner');
set local role authenticated; set local request.jwt.claim.sub='81000000-0000-4000-8000-000000000001';
