set local role authenticated; set local request.jwt.claim.sub='81000000-0000-4000-8000-000000000003';
select ok(not exists(select 1 from claims where id='83000000-0000-4000-8000-000000000001'),'Rejected competitor cannot read owner evidence');
select ok(pg_temp.attempt('verify_owner','{"claim_id": "83000000-0000-4000-8000-000000000001", "decision": "APPROVED"}','42501'),'Unrelated user cannot verify');
set local role authenticated; set local request.jwt.claim.sub='81000000-0000-4000-8000-000000000004';
select ok(not exists(select 1 from claims where id='83000000-0000-4000-8000-000000000001'),'ADMIN cannot read private owner evidence');
select ok(pg_temp.attempt('verify_owner','{"claim_id": "83000000-0000-4000-8000-000000000001", "decision": "APPROVED"}','42501'),'Unrelated ADMIN cannot verify');
set local role authenticated; set local request.jwt.claim.sub='81000000-0000-4000-8000-000000000002';
select ok((select owner_proof_text='Secret owner detail not in the public LOST listing' from claims where id='83000000-0000-4000-8000-000000000001'),'Selected holder reads owner evidence');
select ok(pg_temp.attempt('verify_owner','{"claim_id": "83000000-0000-4000-8000-000000000001", "decision": "REJECTED"}','00000'),'Holder rejects mismatching owner proof');
select ok((select status='REJECTED' from claims where id='83000000-0000-4000-8000-000000000001'),'claims REJECTED');
select ok((select status='OPEN' from items where id='82000000-0000-4000-8000-000000000001'),'items OPEN');
select ok(pg_temp.attempt('submit_found_response','{"item_id": "82000000-0000-4000-8000-000000000001", "request_id": "83000000-0000-4000-8000-000000000003", "proof_text": "Distinct private description of the held wallet"}','00000'),'Can respond again after mismatch');
set local role authenticated; set local request.jwt.claim.sub='81000000-0000-4000-8000-000000000001';
select ok(pg_temp.attempt('review_claim','{"claim_id": "83000000-0000-4000-8000-000000000003", "decision": "APPROVED"}','00000'),'Select replacement response');
select ok(pg_temp.attempt('withdraw_match','{"claim_id": "83000000-0000-4000-8000-000000000003"}','00000'),'Owner may withdraw unverified selection');
select ok((select status='OPEN' from items where id='82000000-0000-4000-8000-000000000001'),'items OPEN');
set local role authenticated; set local request.jwt.claim.sub='81000000-0000-4000-8000-000000000002';
select ok(pg_temp.attempt('submit_found_response','{"item_id": "82000000-0000-4000-8000-000000000001", "request_id": "83000000-0000-4000-8000-000000000004", "proof_text": "Distinct private description of the held wallet"}','00000'),'Final candidate response');
set local role authenticated; set local request.jwt.claim.sub='81000000-0000-4000-8000-000000000001';
select ok(pg_temp.attempt('review_claim','{"claim_id": "83000000-0000-4000-8000-000000000004", "decision": "APPROVED"}','00000'),'Owner selects final candidate');
select ok(pg_temp.attempt('submit_owner_proof','{"claim_id": "83000000-0000-4000-8000-000000000004", "proof_text": "Secret owner detail not in the public LOST listing"}','00000'),'Owner submits proof for final candidate');
set local role authenticated; set local request.jwt.claim.sub='81000000-0000-4000-8000-000000000002';
set local request.jwt.claim.sub='81000000-0000-4000-8000-000000000003';
select ok(pg_temp.attempt('submit_found_response','{"item_id":"82000000-0000-4000-8000-000000000001","request_id":"83000000-0000-4000-8000-000000000006","proof_text":"A queued finder response while owner is being verified"}'),'OPEN LOST still accepts queued responses while selected holder verifies');
set local request.jwt.claim.sub='81000000-0000-4000-8000-000000000002';
select ok(pg_temp.attempt('verify_owner','{"claim_id": "83000000-0000-4000-8000-000000000004", "decision": "APPROVED"}','00000'),'Holder verifies actual owner');
select ok((select status='IN_PROGRESS' from items where id='82000000-0000-4000-8000-000000000001'),'items IN_PROGRESS');
select ok((select ownership_verified_at is not null from claims where id='83000000-0000-4000-8000-000000000004'),'Verified timestamp persisted');
set local request.jwt.claim.sub='81000000-0000-4000-8000-000000000001';
select ok((select status='REJECTED' from claims where id='83000000-0000-4000-8000-000000000006'),'Final verification rejects later queued responses');
