select ok(pg_temp.attempt('withdraw_match','{"claim_id": "83000000-0000-4000-8000-000000000004"}','22023'),'Cannot withdraw verified match');
select ok(pg_temp.attempt('propose_handover',jsonb_build_object('claim_id','83000000-0000-4000-8000-000000000004','revision',0,'location','Campus security office','meeting_at',now()+interval '1 day')),'Holder proposes public handover');
set local role authenticated; set local request.jwt.claim.sub='81000000-0000-4000-8000-000000000001';
select ok(pg_temp.attempt('accept_handover','{"claim_id": "83000000-0000-4000-8000-000000000004", "revision": 1}','00000'),'Owner accepts proposal');
