select ok(pg_temp.attempt('resolve_lost','{"item_id": "82000000-0000-4000-8000-000000000002"}','00000'),'Independent recovery still works with pending responses');
select ok(not exists(select 1 from claims where item_id='82000000-0000-4000-8000-000000000002' and status='PENDING'),'Independent recovery clears pending responses');
select * from finish();
rollback;
